-- query_capiro_data catalog text for the readiness columns, which now follow the
-- saved Strategy intake when one exists (see the preceding view migration).
BEGIN;
SET LOCAL ROLE capiro_private_projection_owner;
COMMENT ON VIEW meri_private.client_objectives IS '{"description":"Current nondeleted standalone client objectives, including complete stored business fields and readiness. Independent of Strategy goals and advocacy history.","grain":"One current nondeleted standalone Objective per canonical id, within its client_id.","primaryKey":["client_id","id"],"relationships":[],"limitations":["Only currently authorized, nonarchived clients and nondeleted Objectives. General covers the current visible client roster; selected-client scope cannot broaden it.","No automatic-context three-item sample or hidden list cap. Explicit SQL filters/limits and output bounds still apply; returned rows do not establish source-universe completeness.","Create-request hashes, revision history, Strategy intake answers and operational plans/ledgers are not exposed. An Objective saved through the Strategy intake (readiness_basis strategy_intake) keeps its answers outside these columns, so its outcome, government_problem, ask_type and minimum_win can be empty.","Current Objective version and readiness do not authorize a write."],"freshnessField":"updated_at"}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_outcome IS '{"description":"Outcome has content after the canonical ECMAScript whitespace trim. Counts toward readiness only when readiness_basis is objective_fields.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_government_problem IS '{"description":"Government problem has content after the canonical whitespace trim. Counts toward readiness only when readiness_basis is objective_fields.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_ask_type IS '{"description":"Ask type is one of the five supported Objective ask types. Counts toward readiness only when readiness_basis is objective_fields.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_minimum_win IS '{"description":"Minimum win has content after the canonical whitespace trim. Counts toward readiness only when readiness_basis is objective_fields.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_completed_fields IS '{"description":"Number of complete required readiness fields: zero through three for strategy_intake, zero through four for objective_fields.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_required_fields IS '{"description":"Three for strategy_intake (objective type, goal statement, owner) or four for objective_fields (outcome, government problem, ask type, minimum win), matching objectiveReadiness. Limits, target date and Meri context are never required.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_is_ready IS '{"description":"Every required field for readiness_basis is complete. This does not change the stored lifecycle status.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_basis IS '{"description":"Readiness rule in force: strategy_intake when the current version was saved through the Strategy intake, otherwise objective_fields.","nullable":false,"enum":["strategy_intake","objective_fields"]}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_objective_type IS '{"description":"Strategy intake objective type is selected. Null when readiness_basis is objective_fields."}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_goal IS '{"description":"Strategy intake goal statement has content after the whitespace trim. Null when readiness_basis is objective_fields."}';
COMMENT ON COLUMN meri_private.client_objectives.readiness_owner IS '{"description":"Strategy intake owner is set. Null when readiness_basis is objective_fields."}';
COMMIT;
